// === 🧠 VISION AGGREGATION LOGIC ===
const INPUT_DATA = items[0].json;
const history = INPUT_DATA.history;

// 1. Retrieve the outputs of the 4 specific tasks
// We search from the end to get the most recent execution
const findResult = (taskId) => {
    const record = history.slice().reverse().find(h => h.task_id === taskId);
    return record ? record.output : null;
};

const adherence = findResult('verify_adherence');
const perspective = findResult('verify_perspective');
const overlaps = findResult('check_overlaps');
const artifacts = findResult('detect_artifacts');

// 2. Determine Failures
const failures = [];

if (adherence && !adherence.pass) {
    failures.push(`[Adherence Failure]: ${adherence.critique}`);
}
if (perspective && !perspective.pass) {
    failures.push(`[Perspective Failure]: ${perspective.critique}`);
}
if (overlaps && !overlaps.pass) {
    failures.push(`[Overlap/Clutter Failure]: ${overlaps.critique}`);
}
if (artifacts && !artifacts.pass) {
    failures.push(`[Technical Glitch Failure]: ${artifacts.critique}`);
}

const passed = failures.length === 0;
let newHistory = [...history];

// 3. IF FAILED: Inject Error Message into History
if (!passed) {
    const errorReport = {
        phase_id: "3",
        agent_id: "system", // Special ID for system messages
        task_id: "error_report",
        task_instruction: "Aggregation of Vision Failures",
        output: {
            reasoning: "Vision checks failed. Injecting feedback for loop.",
            message: `*** CRITICAL VISUAL FAILURES DETECTED ***\nThe following issues must be fixed in the next iteration:\n\n${failures.join('\n')}\n\nDIRECTIVE: Refactor the Python code specifically to address these visual bugs. Do not simply regenerate the same code.`
        }
    };
    newHistory.push(errorReport);
}

// 4. Output Final Verdict
return [{
    json: {
        ...INPUT_DATA,
        history: newHistory,

        // Hoist final decision for the IF node
        vision_pass: passed,
        vision_critique: failures.join(' | ')
    }
}];

// === 🐛 EXECUTION ERROR HANDLER ===
const inputData = items[0].json;

// 1. Extract the Error Message
let errorText = "Unknown Error";

// Check if the error is nested in an 'error' object (standard n8n HTTP error output)
if (inputData.error) {
    if (inputData.error.message) {
        errorText = inputData.error.message;
    } else if (inputData.error.response && inputData.error.response.data) {
        const rawData = inputData.error.response.data;
        if (typeof rawData === 'object') {
            errorText = JSON.stringify(rawData);
        } else {
            errorText = rawData.toString();
        }
    }
}

// 2. PREPARE CONTEXT
// Since you confirmed the data passes through, we just clone the input.
// We remove the 'error' key so we don't pass the raw error object back to the AI.
const previousData = { ...inputData };
delete previousData.error; 

// 3. Create History Record
const errorRecord = {
    phase_id: "3",
    agent_id: "system",
    task_id: "execution_error",
    task_instruction: "Run Python Code",
    output: {
        status: "failed",
        reasoning: "Runtime Error",
        message: `*** PYTHON RUNTIME ERROR ***\nThe code crashed with this error:\n\n${errorText}\n\nDIRECTIVE: Fix the code based on this error.`
    }
};

// 4. Merge and Send Back to Loop
return [{
    json: {
        ...previousData, // Keep all your existing context (history, debug_query, etc.)
        history: [...(previousData.history || []), errorRecord],
        vision_pass: false 
    }
}];

// === 🖼️ VIEW BASE64 IMAGE ===
const item = items[0].json;
const base64String = item.base64_img_string;

if (!base64String) {
    throw new Error("No image data found. The Artist agent likely failed to parse the output.");
}

// Default to png, but use dynamic type if available
const mime = item.base64_img_string_mime || "image/png";
const ext = mime.split('/')[1] || "png";

return [{
    json: item, 
    binary: {
        data: {
            data: base64String,
            mimeType: mime,
            fileExtension: ext,
            fileName: `generated_image.${ext}`
        }
    }
}];

// === 🔄 FEEDBACK LOOP INJECTOR ===
// Takes the failure reason from Phase 5 (Issue Aggregator) and injects it 
// into history as a Phase 4 artifact. When the loop restarts Phase 4, 
// the Image Planner will see this "Output" in its history and adjust 
// the next prompt accordingly.

const inputData = items[0].json;
const feedback = inputData.debug_response; // The output from Issue Aggregator

// Safety check
if (!feedback) {
    throw new Error("No feedback data found in 'debug_response' to inject.");
}

// Create the "Trojan Horse" history record
// We mark it as AGENT_ID: "image_planner" so the LLM treats it as 
// "My own previous realization/note".
const injectionRecord = {
  phase_id: "4",
  agent_id: "image_planner", 
  task_id: "receive_quality_feedback",
  task_instruction: "Review Quality Assurance Feedback.",
  output: {
    status: "REJECTED",
    critique: "The previous image failed the Phase 5 Quality Gate.",
    warning: feedback.warning_message || "Quality checks failed.",
    REQUIRED_FIX: feedback.fix_instructions || "Review constraints and try again."
  }
};

// Return updated data with the new history item appended
return [{
  json: {
    ...inputData,
    history: [...(inputData.history || []), injectionRecord]
    // We intentionally keep 'base64_string' (the bad image) 
    // so the Planner has context on what it generated last time.
  }
}];

// 1. Get the merged data
const data = items[0].json;

// 2. Normalize the booleans
const hasMath = data.math_found === true;
const hasVisual = data.image_request === true;

let route = "neither";
let output = { status: "ambiguous" };

// 3. The Decision Logic
if (hasMath && hasVisual) {
  route = "ready";
  output = {
    problem: data.math_text,
    description: data.visual_text,
    status: "complete"
  };
} else if (hasMath && !hasVisual) {
  route = "math_only";
  output = {
    problem: data.math_text,
    status: "needs_description"
  };
} else if (!hasMath && hasVisual) {
  route = "visual_only";
  output = {
    description: data.visual_text,
    warning: "Direct visual request (No math problem context).",
    status: "direct_draw"
  };
}

// 4. Return the final payload (without original_query)
return [{
    json: {
        route,
        ...output,
        ...data 
    }
}];

// 1. Grab all 12 items directly from the Phase 6 Output
const finalData = $('Phase 6 - Output').first().json;
const { api_key, ...safeData } = finalData;
const config = finalData.config || {};
const webhookUrl = config.gui_webhook_url;

// 2. Add the completion status to the bundle
const finalPayload = {
    ...safeData,
    phase_id: "-", 
    agent_id: "-", 
    task_id: "-", 
    status: "completed", 
    timestamp: new Date().toISOString()
};

// 3. Fire the "Fat JSON" to the Cloud Run Listener
if (config.enable_gui_logging === true && webhookUrl) {
    try {
        await this.helpers.httpRequest({
            method: 'POST',
            url: webhookUrl,
            headers: { 'Content-Type': 'application/json' },
            body: finalPayload,
            json: true,
            timeout: 5000
        });
    } catch (e) {
        console.error("Final broadcast failed:", e.message);
    }
}

return [{ json: { status: "Workflow Complete", job_id: finalData.job_id } }];

