const input = items[0].json;
const config = input.config || $('Load Phase 3 Config').item.json.config;

const needs3D = input.needs_3d_planning === true;
const needsPrim = input.needs_arrangement_planning === true;

let combinedDirectives = [];

// 2. Navigate to the scaffolding_designer tasks in the config
const tasks = config.phases["3"].agents.scaffolding_designer.tasks;

// 3. Parse the JSON strings from the config to extract just the text
if (needs3D) {
    const rawResult3D = JSON.parse(tasks.inject_3d_constraints.result);
    combinedDirectives.push(rawResult3D.situational_directives);
}

if (needsPrim) {
    const rawResultPrim = JSON.parse(tasks.inject_primitives_constraints.result);
    combinedDirectives.push(rawResultPrim.situational_directives);
}

// 4. If no directives are needed, set TASK_ID to skip
if (combinedDirectives.length === 0) {
    return [{
        json: {
            ...input,
            TASK_ID: "skip"
        }
    }];
}

// 5. Pass the combined string into the 'directives' variable for the UA to inject
return [{
    json: {
        ...input,
        PHASE_ID: "3",
        AGENT_ID: "scaffolding_designer", 
        TASK_ID: "inject_multiple_constraints",
        directives: combinedDirectives.join("\n\n") // Maps directly to $directives
    }
}];
